  (* [comment removed for export] *)
  Definition X2HDR (FF FLG : Z) (j24 : list byte) : list cell :=
    [C8 (Z_to_bv 64 0x41b58ab3); C8 (Z_to_bv 64 0x16e85); C8 (Z_to_bv 64 0x814ec); CB 32 j24; C8 (Z_to_bv 64 FLG)].

  (* [comment removed for export] *)
  Lemma x2_hdr : forall (x5 x6 x7 x11 x12 x13 x14 x15 x16 x17 x28 x29 x30 x31 : word) m (FF FLG DT W S size flags mtl : Z)
      (j0 j1 j2 : word) (junk jA jB : list byte) (Q : machine_state -> Prop),
    rw_cells asegs m SPAx2 [CB 128 jA; C8 (Z_to_bv 64 DT); C8 (Z_to_bv 64 W); CB 584 jB] ->
    rw_cells asegs m FF [C8 j0; C8 j1; C8 j2; CB 32 junk; C8 (Z_to_bv 64 FLG)] ->
    rw_cells asegs m (shad FF) [C8 (Z_to_bv 64 0)] ->
    rw_cells asegs m AGOT_X2PC [C8 (Z_to_bv 64 0x814ec)] -> mem_inv asegs m ->
    rw_cells asegs m (Z.shiftr DT 3 + 2147450880) [C1 (Z_to_bv 8 0)] ->
    rw_cells asegs m DT [C4 (Z_to_bv 64 (mtl * 16777217))] -> 0 <= mtl < 256 ->
    stk asegs m lo SPAx2 ->
    ablk FF (FF + 64) -> FF + 64 <= ATOP -> FF mod 64 = 0 -> ablk DT (DT + 8) -> DT mod 8 = 0 ->
    (DT + 8 <= FF \/ FF + 64 <= DT) ->
    rng RNG FF 64 -> rng RNG (shad FF) 8 -> rng RNG SPAx2 728 -> rng RNG DT 8 -> rng RNG (shad DT) 1 ->
    (forall m' (j56 j72 j104 j144 j24 : list byte) (y5 y6 y7 y15 y16 y28 y29 y30 y31 : word),
        munch [(SPAx2, SPAx2 + 728); (FF, FF + 64); (shad FF, shad FF + 8)] m m' -> wmono asegs m m' -> mem_inv asegs m' ->
        rw_cells asegs m' SPAx2 [CB 56 j56; C8 (Z_to_bv 64 (Z.shiftr DT 3 + 2147450880)); C8 (Z_to_bv 64 (mtl * 16777217));
                                 CB 24 j72; C8 (Z_to_bv 64 (Z.shiftr FF 3 + 2147450880)); CB 8 j104; C8 (Z_to_bv 64 FF);
                                 C8 (Z_to_bv 64 FF); C8 (Z_to_bv 64 DT); C8 (Z_to_bv 64 W); CB 576 j144; C8 (Z_to_bv 64 FF)] ->
        rw_cells asegs m' FF (X2HDR FF FLG j24) ->
        rw_cells asegs m' (shad FF) FDSH ->
        rw_cells asegs m' (Z.shiftr DT 3 + 2147450880) [C1 (Z_to_bv 8 0)] ->
        rw_cells asegs m' DT [C4 (Z_to_bv 64 (mtl * 16777217))] ->
        stk asegs m' lo SPAx2 ->
        evtF asegs RNG Q
          (MS (mkR (Z_to_bv 64 0x81674) (Z_to_bv 64 SPAx2) gp tp y5 y6 y7 (Z_to_bv 64 SP) (Z_to_bv 64 SPAx2)
                   (Z_to_bv 64 (W + 624)) (Z_to_bv 64 0) (Z_to_bv 64 112) (Z_to_bv 64 W)
                   (Z_to_bv 64 (Z.shiftr DT 3 + 2147450880)) y15 y16
                   (Z_to_bv 64 (Z.shiftr FF 3 + 2147450880))
                   (Z_to_bv 64 S) (Z_to_bv 64 FF) s4 (Z_to_bv 64 W) (Z_to_bv 64 mtl) (Z_to_bv 64 size) (Z_to_bv 64 2147450880)
                   (Z_to_bv 64 flags) s10 (Z_to_bv 64 (W + 624)) y28 y29 y30 y31)
              F (Z_to_bv 64 0x515b0) fc None m' (seg_rom asegs))) ->
    evtF asegs RNG Q
      (MS (mkR (Z_to_bv 64 0x81570) (Z_to_bv 64 SPAx2) gp tp x5 x6 x7 (Z_to_bv 64 SP) (Z_to_bv 64 SPAx2)
               (Z_to_bv 64 FF) x11 x12 x13 x14 x15 x16 x17
