  (* [comment removed for export] *)
  Lemma x2_epi : forall (x1 x5 x6 x7 x10 x11 x12 x13 x14 x15 x16 x18 x19 x20 x21 x22 x23 x24 x25 x27 x28 x29 x30 x31 : word)
      m (FF FLG rv : Z) (j0 : word) (ja jb : list byte),
    rw_cells asegs m (Z.shiftr FF 3 + 2147450880) FDSH ->
    rw_cells asegs m FF [C8 j0] -> rw_cells asegs m (FF + 56) [C8 (Z_to_bv 64 FLG)] -> rw_cells asegs m FLG [C1 (Z_to_bv 8 1)] ->
    rw_cells asegs m (SP + -104) FRBx2 ->
    rw_cells asegs m SPAx2 [CB 112 ja; C8 (Z_to_bv 64 FF); C8 (Z_to_bv 64 FF); CB 600 jb] ->
    stk asegs m lo SPAx2 -> stk asegs m (SPAx2 + 728) (SP + -104) -> mem_inv asegs m ->
    ablk FF (FF + 64) -> FF + 64 <= ATOP -> FF mod 64 = 0 -> ablk FLG (FLG + 1) -> FLG + 1 <= ATOP -> (FLG + 1 <= FF \/ FF + 64 <= FLG) ->
    rng RNG FF 64 -> rng RNG (shad FF) 8 -> rng RNG FLG 1 -> rng RNG SPAx2 728 ->
    evtF asegs RNG (fun ms' => exists mp m' (y5 y6 y7 y11 y12 y13 y14 y15 y16 y17 y28 y29 y30 y31 : word),
        ms' = RETx m' y5 y6 y7 (Z_to_bv 64 rv) y11 y12 y13 y14 y15 y16 y17 y28 y29 y30 y31
        /\ munch [(Z.shiftr FF 3 + 2147450880, Z.shiftr FF 3 + 2147450880 + 8); (FF, FF + 8)] m mp /\ wmono asegs m mp
        /\ mem_inv asegs mp
        /\ munch [(FLG, FLG + 1)] mp m' /\ wmono asegs mp m' /\ mem_inv asegs m'
        /\ stk asegs m' lo SP /\ rw_cells asegs m' FLG [C1 (Z_to_bv 8 0)])
      (MS (mkR x1 (Z_to_bv 64 SPAx2) gp tp x5 x6 x7 (Z_to_bv 64 SP) (Z_to_bv 64 SPAx2) x10 x11 x12 x13 x14 x15 x16
               (Z_to_bv 64 (Z.shiftr FF 3 + 2147450880)) x18 x19 x20 x21 x22 x23 x24 x25 (Z_to_bv 64 rv) x27 x28 x29 x30 x31)
